export interface QuestionBankOption {
  letter: 'A' | 'B' | 'C' | 'D' | 'E';
  text: string;
  correct: boolean;
}

export interface QuestionBankSupport {
  /** Label shown above the support text, e.g. TEXTO I. */
  label?: string;
  /** Clean title without decorative Markdown/HTML markers. */
  title?: string;
  /** Author/byline shown below the title. */
  author?: string;
  /** Semantic paragraphs; line breaks inside a paragraph preserve verse/dialogue. */
  paragraphs: string[];
  /** Bibliographic source shown at the bottom of the same support card. */
  source?: string;
}

export interface QuestionBankProvenance {
  pdf: string;
  questionPage?: number;
  answerPage?: number;
}

export interface QuestionBankQuality {
  status: 'verified' | 'warning';
  warnings: string[];
}

export interface QuestionBankEmphasisNote {
  target: string;
  reason: string;
}

export interface QuestionBankItem {
  id: string;
  subjectId: SubjectId;
  subjectTitle: string;
  listId: string;
  listTitle: string;
  questionNumber: number;
  support?: QuestionBankSupport;
  provenance?: QuestionBankProvenance;
  quality?: QuestionBankQuality;
  emphasisNotes?: QuestionBankEmphasisNote[];
  /** Legacy serialized support, retained for localStorage/data migration fallback. */
  readingText?: string;
  statement: string;
  options: QuestionBankOption[];
  correctLetter: 'A' | 'B' | 'C' | 'D' | 'E';
  banca: string;
  /** Native language/subdivision of the source bank. Legacy Portuguese items omit this field. */
  language?: 'pt' | 'en';
  isCustom?: boolean;
}

export interface SubjectMetadata {
  id: SubjectId;
  title: string;
  shortTitle: string;
  description: string;
  iconName: string;
}

